// Bug-fix question: the buggy code is shown, the student picks the fix.
// `fixed` is the corrected program; the verifier compiles it and checks `expect`.
const bug = (skill: string, prompt: string, buggy: string, options: string[], correct: number, hint: string, explain: string, fixed: string, expect: string, wrap: "main" | "class" = "main") => ({
  ...choice(skill, prompt, options, correct, hint, explain, buggy, { src: fixed, wrap, expect }),
  label: "Find and fix the bug",
});

